css:
.chart {
  display: flex;
  flex-direction: column;
  gap: var(--sw-space-5);
  color: var(--sw-ink);
}
.headline {
  font-size: 64px;
  font-weight: 700;
}
.bars {
  display: flex;
  flex-direction: column;
  gap: var(--sw-space-4);
}
.row {
  display: flex;
  align-items: center;
  gap: var(--sw-space-4);
}
.label {
  width: 320px;
  font-size: 32px;
}
.track {
  flex-grow: 1;
  height: 56px;
  border-radius: var(--sw-radius-sm);
  background: var(--sw-chip);
}
.bar {
  width: calc(var(--v) * 1%);
  height: 100%;
  border-radius: var(--sw-radius-sm);
  background: var(--sw-accent);
}
.bar.is-alert {
  background: var(--sw-bad);
}
.note {
  font-size: 28px;
  color: var(--sw-muted);
}
